class Solution {
public:
    void inorder(TreeNode*node,vector<int>& answer){
        if(node==nullptr){
            return;
        }
        inorder(node->left,answer);
        answer.push_back(node->val);
        inorder(node->right,answer);
    }
    int kthSmallest(TreeNode* root, int k) {
        vector<int>answer;
        inorder(root,answer);
        return answer[k-1];
    }
};
