## 5. Parent waits with waitpid (specific child)
```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>

int main() {
    pid_t pid = fork();

    if (pid == 0) {
        printf("Child (PID: %d) working...\n", getpid());
        sleep(2);
        printf("Child done\n");
        exit(42);  // exit with specific status code
    } else {
        int status;
        printf("Parent waiting for specific child PID: %d\n", pid);

        waitpid(pid, &status, 0);  // wait for specific child

        if (WIFEXITED(status)) {
            printf("Child exited with status: %d\n", WEXITSTATUS(status));
        }
        printf("Parent done\n");
    }
    return 0;
}
```
**Key concept:** `waitpid()` waits for a **specific** child by PID, and you can read the child's **exit code** using `WEXITSTATUS`.

