## Part 2 — C Code Implementation:

```c
#include <stdio.h>

int main() {
    int n = 4;
    char process[] = {'1', '2', '3', '4'};
    int at[] = {0, 0, 0, 0};    // Arrival Time
    int bt[] = {7, 5, 3, 6};    // Burst Time
    int ct[4], tat[4], wt[4], rt[4];

    // Calculate Completion Time (FCFS - sequential)
    ct[0] = at[0] + bt[0];
    for (int i = 1; i < n; i++) {
        ct[i] = ct[i-1] + bt[i];
    }

    // Calculate TAT, WT, RT
    for (int i = 0; i < n; i++) {
        tat[i] = ct[i] - at[i];           // Turnaround Time
        wt[i]  = tat[i] - bt[i];          // Waiting Time
        rt[i]  = ct[i] - bt[i] - at[i];  // Response Time (same as WT for FCFS)
    }

    // Print Gantt Chart
    printf("\nGantt Chart:\n|");
    for (int i = 0; i < n; i++) {
        printf(" P%c |", process[i]);
    }
    printf("\n0");
    for (int i = 0; i < n; i++) {
        printf("    %d", ct[i]);
    }
    printf("\n");

    // Print Results Table
    printf("\n%-10s %-15s %-12s %-18s %-15s %-15s %-15s\n",
           "Process", "Arrival Time", "Burst Time",
           "Completion Time", "Turnaround Time", "Waiting Time", "Response Time");
    printf("--------------------------------------------------------------------------------------------\n");

    for (int i = 0; i < n; i++) {
        printf("%-10c %-15d %-12d %-18d %-15d %-15d %-15d\n",
               process[i], at[i], bt[i], ct[i], tat[i], wt[i], rt[i]);
    }

    // Averages
    float avg_tat = 0, avg_wt = 0, avg_rt = 0;
    for (int i = 0; i < n; i++) {
        avg_tat += tat[i];
        avg_wt  += wt[i];
        avg_rt  += rt[i];
    }

    printf("\nAverage Turnaround Time : %.2f", avg_tat / n);
    printf("\nAverage Waiting Time    : %.2f", avg_wt / n);
    printf("\nAverage Response Time   : %.2f\n", avg_rt / n);

    return 0;
}
```

