```cpp
class Solution {
public:
    bool dfs(int i, vector<int>& vis, vector<int>& onPath,
             vector<vector<int>>& adj, stack<int>& s) {
        vis[i] = true;
        onPath[i] = true;

        for(int neig : adj[i]){
            if(!vis[neig]){
                if(dfs(neig, vis, onPath, adj, s))
                    return true;
            }
            else if(onPath[neig]){
                return true;
            }
        }

        onPath[i] = false;  // BUG 3 (minor): you forgot this
        s.push(i);
        return false;
    }

    vector<int> findOrder(int numCourses, vector<vector<int>>& prerequisites) {
        vector<int> ans;
        stack<int> s;
        vector<int> vis(numCourses, 0);
        vector<int> onPath(numCourses, 0);
        vector<vector<int>> adj(numCourses);

        for(auto& p : prerequisites){
            adj[p[0]].push_back(p[1]);
        }

        for(int i = 0; i < numCourses; i++){
            if(!vis[i]){
                if(dfs(i, vis, onPath, adj, s)){
                    return {};  // cycle exists
                }
            }
        }

        while(!s.empty()){
            ans.push_back(s.top());
            s.pop();
        }
        return ans;
    }
};
