### Explanation of each requirement:

| Requirement | How it's handled |
|---|---|
| **fork() purpose** | Creates two independent processes from one |
| **Parent prints even** | `else` block (pid > 0) prints even numbers |
| **Child prints odd** | `else if(pid == 0)` block prints odd numbers |
| **Both execute independently** | No synchronization between printing loops |
| **Parent waits for child** | `wait(NULL)` holds parent until child calls `exit(0)` |
| **Error handling** | `if(pid < 0)` handles fork failure |

Here are all the combinations with simple, clean programs:

---

## 1. Child terminates before Parent (normal case)
```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>

int main() {
    pid_t pid = fork();

    if (pid == 0) {
        // Child
        printf("Child (PID: %d) starting\n", getpid());
        sleep(1);
        printf("Child finished first\n");
        exit(0);
    } else {
        // Parent
        printf("Parent (PID: %d) waiting...\n", getpid());
        wait(NULL);  // parent waits for child
        printf("Parent confirmed child done, now parent exits\n");
    }
    return 0;
}
```
**Output:**
```
Parent (PID: 1234) waiting...
Child (PID: 1235) starting
Child finished first
Parent confirmed child done, now parent exits
```

---

## 2. Parent terminates before Child (Orphan Process)
```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

int main() {
    pid_t pid = fork();

    if (pid == 0) {
        // Child runs longer
        sleep(5);
        // After parent dies, child is adopted by systemd (PID 1)
        printf("Child (PID: %d), Parent PID now: %d\n", getpid(), getppid());
        printf("Child finishing\n");
        exit(0);
    } else {
        // Parent exits immediately
        printf("Parent (PID: %d) exiting before child!\n", getpid());
        exit(0);  // no wait() — parent doesn't wait
    }
    return 0;
}
```
**Key concept:** Child becomes an **Orphan** — adopted by `systemd` (PID 1) automatically.

---

## 3. Zombie Process (Child finishes but Parent never calls wait)
```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

int main() {
    pid_t pid = fork();

    if (pid == 0) {
        // Child exits immediately
        printf("Child (PID: %d) exiting now\n", getpid());
        exit(0);
    } else {
        // Parent sleeps but never calls wait()
        // Child becomes ZOMBIE during this time
        printf("Parent (PID: %d) sleeping, child is now a zombie!\n", getpid());
        printf("Run: ps -aux | grep Z   in another terminal to see zombie\n");
        sleep(15);  // open another terminal and check during this time
        printf("Parent exiting without ever calling wait()\n");
    }
    return 0;
}
```
**Key concept:** Child is in `Z (zombie)` state — finished but entry still in process table because parent never collected exit status via `wait()`.

**To see the zombie while program runs:**
```bash
# In another terminal
ps -aux | grep Z
```

---

## 4. Parent and Child run simultaneously (No wait, No sleep)
```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

int main() {
    pid_t pid = fork();

    if (pid == 0) {
        for (int i = 0; i < 5; i++) {
            printf("Child  (PID: %d) -> count: %d\n", getpid(), i);
        }
        exit(0);
    } else {
        for (int i = 0; i < 5; i++) {
            printf("Parent (PID: %d) -> count: %d\n", getpid(), i);
        }
    }
    return 0;
}
```
**Key concept:** Output order is **unpredictable** — CPU scheduler decides who runs when. Run it multiple times, output order changes each time.

---

## 5. Parent waits with waitpid (specific child)
```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>

int main() {
    pid_t pid = fork();

    if (pid == 0) {
        printf("Child (PID: %d) working...\n", getpid());
        sleep(2);
        printf("Child done\n");
        exit(42);  // exit with specific status code
    } else {
        int status;
        printf("Parent waiting for specific child PID: %d\n", pid);

        waitpid(pid, &status, 0);  // wait for specific child

        if (WIFEXITED(status)) {
            printf("Child exited with status: %d\n", WEXITSTATUS(status));
        }
        printf("Parent done\n");
    }
    return 0;
}
```
**Key concept:** `waitpid()` waits for a **specific** child by PID, and you can read the child's **exit code** using `WEXITSTATUS`.

---

## 6. Multiple children, Parent waits for all
```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>

int main() {
    pid_t pid1, pid2, pid3;

    pid1 = fork();
    if (pid1 == 0) {
        printf("Child 1 (PID: %d) sleeping 3 seconds\n", getpid());
        sleep(3);
        printf("Child 1 done\n");
        exit(0);
    }

    pid2 = fork();
    if (pid2 == 0) {
        printf("Child 2 (PID: %d) sleeping 1 second\n", getpid());
        sleep(1);
        printf("Child 2 done\n");
        exit(0);
    }

    pid3 = fork();
    if (pid3 == 0) {
        printf("Child 3 (PID: %d) sleeping 2 seconds\n", getpid());
        sleep(2);
        printf("Child 3 done\n");
        exit(0);
    }

    // Parent waits for ALL children
    printf("Parent waiting for all 3 children...\n");
    for (int i = 0; i < 3; i++) {
        pid_t done = wait(NULL);
        printf("Parent: child %d finished\n", done);
    }
    printf("All children done, parent exits\n");

    return 0;
}
```
**Key concept:** `wait()` returns the PID of whichever child finishes first — so children finish in order of their sleep time (Child 2 → Child 3 → Child 1).

---

## 7. Child using exec() to run a different program
```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>

int main() {
    pid_t pid = fork();

    if (pid == 0) {
        printf("Child (PID: %d) replacing itself with 'ls' command\n", getpid());
        // Child replaces its entire process image with 'ls'
        execlp("ls", "ls", "-l", NULL);
        // This line only runs if exec fails
        printf("exec failed!\n");
        exit(1);
    } else {
        printf("Parent (PID: %d) waiting for child to finish ls\n", getpid());
        wait(NULL);
        printf("Parent done\n");
    }
    return 0;
}
```
**Key concept:** `exec()` **replaces** the child process with a completely different program (`ls` here) — child's code after `execlp` never runs.

