* `1 <= prices.length <= 10^5`
* `0 <= prices[i] <= 10^4`

class Solution {
public:
    int maxProfit(vector<int>& prices) {
        int start =0;
        int mini = *min_element(prices.begin(),prices.end());
        for(int i=0;i<prices.size();i++){
            if(prices[i]==mini){
                start=i;
            }
        }
        if(start==prices.size()-1){
            return 0;
        }
        vector<int>ahead;
        for(int i=start+1;i<prices.size();i++){
            ahead.push_back(prices[i]);
        }
        int maxi=*max_element(ahead.begin(),ahead.end());
        return maxi-prices[start];
    }
};
